#!/usr/bin/env python3
"""Yosys synthesis driver.

Elaborates one IP, maps it onto the portfolio's generic reference standard
cell library and emits a gate level netlist plus an area/cell-count report.

The flow deliberately uses a generic library rather than any FPGA vendor
technology: the goal is a portable, reproducible check that the RTL is
synthesisable and a relative area figure that can be tracked over time.
"""
from __future__ import annotations

import argparse
import json
import re
import subprocess
import sys
from pathlib import Path

SYNTH_SCRIPT = """\
# Auto-generated by run_synth.py - do not edit.
#
# The library is read twice, and both reads are necessary.
#
#   read_liberty -lib   declares every cell as a blackbox with its real port
#                       directions. Without it, the cells that dfflibmap and
#                       abc instantiate have no known interface, so `check`
#                       reports every mapped flip-flop output as an undriven
#                       wire and `check -assert` fails on a netlist that is in
#                       fact correct.
#
#   -liberty on dfflibmap and abc supplies the timing and area data used to
#                       choose cells.
read_liberty -lib {liberty}
{read_cmds}
hierarchy -check -top {top}{chparams}
proc
opt_expr
opt_clean
check
fsm
opt
memory -nomap
opt_clean
memory_map
opt -full
techmap
opt -fast
dfflibmap -liberty {liberty}
abc -liberty {liberty}
setundef -zero
# splitnets without -ports: splitting the module ports as well rewrites the
# interface into one wire per bit and leaves the original vector's drivers
# pointing at nets that no longer exist, so every output reads as undriven and
# `check -assert` fails. Internal nets are still split, which is what the
# netlist writer wants.
splitnets
opt_clean -purge
check -assert
tee -o {stat_json} stat -liberty {liberty} -json
tee -a {log} stat -liberty {liberty}
write_verilog -noattr -noexpr {netlist}
write_json {json_out}
"""


def parse_args() -> argparse.Namespace:
    p = argparse.ArgumentParser(description=__doc__)
    p.add_argument("--yosys", default="yosys")
    p.add_argument("--top", required=True)
    p.add_argument("--name", required=True)
    p.add_argument("--out-dir", required=True)
    p.add_argument("--report", required=True)
    p.add_argument("--liberty", required=True)
    p.add_argument("--param", action="append", default=[])
    p.add_argument("--define", action="append", default=[])
    p.add_argument("--sources", nargs="+", required=True)
    return p.parse_args()


# Yosys 0.67 aborts with this internal assertion when `hierarchy -chparam` is
# used on a top module that instantiates a parameterised submodule - even when
# the value passed equals the RTL default. It is a tool defect, not an RTL one:
# the identical design elaborates and maps cleanly with the override omitted.
#
# Seen on the WebAssembly build (yowasp-yosys); a native build may not have it.
# The driver retries without the overrides rather than reporting a failure it
# cannot act on, and says so loudly in both the log and the report.
CHPARAM_BUG_SIGNATURE = "modules_.count(module->name) == 0"


def build_script(args: argparse.Namespace, out_dir: Path,
                 with_params: bool = True) -> str:
    defines = " ".join(f"-D{d}" for d in ["SYNTHESIS"] + args.define)
    read_cmds = "\n".join(
        f"read_verilog -sv {defines} {Path(s).resolve()}" for s in args.sources)

    chparams = ""
    if with_params:
        for item in args.param:
            key, _, value = item.partition("=")
            chparams += f" -chparam {key.strip()} {value.strip()}"

    return SYNTH_SCRIPT.format(
        read_cmds=read_cmds,
        top=args.top,
        chparams=chparams,
        liberty=Path(args.liberty).resolve(),
        netlist=out_dir / f"{args.name}.mapped.v",
        json_out=out_dir / f"{args.name}.netlist.json",
        stat_json=out_dir / f"{args.name}.stat.json",
        log=out_dir / f"{args.name}.stat.txt",
    )


def summarise(stat_json: Path, log: str) -> dict:
    """Extract a compact area/cell summary from the Yosys statistics."""
    summary: dict = {"cells": {}, "total_cells": 0, "area": None}
    if stat_json.is_file():
        try:
            raw = json.loads(stat_json.read_text(encoding="utf-8"))
            modules = raw.get("modules", {})
            design = raw.get("design", {})
            summary["cells"] = design.get("num_cells_by_type", {})
            summary["total_cells"] = design.get("num_cells", 0)
            summary["area"] = design.get("area")
            summary["modules"] = sorted(modules.keys())
        except (json.JSONDecodeError, AttributeError):
            pass
    if summary["area"] is None:
        match = re.search(r"Chip area for.*?:\s*([0-9.]+)", log)
        if match:
            summary["area"] = float(match.group(1))
    return summary


def main() -> int:
    args = parse_args()

    out_dir = Path(args.out_dir)
    out_dir.mkdir(parents=True, exist_ok=True)
    report = Path(args.report)
    report.parent.mkdir(parents=True, exist_ok=True)

    def run(with_params: bool) -> tuple[subprocess.CompletedProcess, str]:
        path = out_dir / f"{args.name}.ys"
        path.write_text(build_script(args, out_dir, with_params), encoding="utf-8")
        completed = subprocess.run(
            [args.yosys, "-q", "-s", str(path)], capture_output=True, text=True)
        return completed, completed.stdout + completed.stderr

    script_path = out_dir / f"{args.name}.ys"
    proc, log = run(with_params=True)

    parameters_applied = True
    if proc.returncode != 0 and CHPARAM_BUG_SIGNATURE in log and args.param:
        sys.stderr.write(
            f"SYNTH WARNING: {args.name}: this Yosys build aborts on "
            f"'hierarchy -chparam' (internal assertion). Retrying at the RTL "
            f"default parameters; the netlist below is NOT the configuration "
            f"the simulation used.\n")
        proc, retry_log = run(with_params=False)
        log = (log + "\n# ---- retry without -chparam, see "
               "CHPARAM_BUG_SIGNATURE in run_synth.py ----\n" + retry_log)
        parameters_applied = False

    (out_dir / f"{args.name}.yosys.log").write_text(log, encoding="utf-8")

    netlist = out_dir / f"{args.name}.mapped.v"
    ok = proc.returncode == 0 and netlist.is_file()

    result = {
        "ip": args.name,
        "top": args.top,
        "status": "pass" if ok else "fail",
        "parameters": args.param,
        # False means the tool could not apply the overrides and the netlist
        # reflects the RTL defaults instead. Anything comparing area across
        # configurations must check this flag.
        "parameters_applied": parameters_applied,
        "netlist": str(netlist),
        "liberty": str(Path(args.liberty).resolve()),
        **summarise(out_dir / f"{args.name}.stat.json", log),
    }
    report.write_text(json.dumps(result, indent=2), encoding="utf-8")

    if not ok:
        sys.stderr.write(log)
        sys.stderr.write(f"\nSYNTH FAILED: {args.name}\n")
        return 1

    area = result.get("area")
    area_txt = f"{area:.2f}" if isinstance(area, (int, float)) else "n/a"
    print(f"SYNTH PASS: {args.name}  cells={result['total_cells']}  area={area_txt}")
    return 0


if __name__ == "__main__":
    sys.exit(main())
